fn install_cl_x2e_maplispsym(interp: &mut Interp) {
    interp.register_native("cl.maplispsym", 1, aot_cl_x2e_maplispsym);
    interp.register_aot_direct("cl.maplispsym", aot_cl_x2e_maplispsym);
}

/// Register every AOT-compiled function on `interp`. Call after kernel
/// boot so these names override the tree-walked defuns.
pub fn install(interp: &mut Interp) {
    install_cl_x2e_kl_x2d_to_x2d_lisp(interp);
    install_cl_x2e_kl_x2d_to_x2d_lisp_x2d_h(interp);
    install_cl_x2e_rectify_x2d_t(interp);
    install_cl_x2e_currylisp(interp);
    install_cl_x2e_optimise_x2d_application(interp);
    install_cl_x2e_cond_x2d_code(interp);
    install_cl_x2e_wrap(interp);
    install_cl_x2e_fastsymbol_x3f_(interp);
    install_cl_x2e_wrapper(interp);
    install_cl_x2e_maplispsym(interp);
}
